<div class="page-heading"><div><a class="back-link" href="<?= url('student/support') ?>">← Help centre</a><span class="eyebrow"><?= e($ticket['ticket_number']) ?></span><h1><?= e($ticket['subject']) ?></h1><p><?= e(ucfirst($ticket['category'])) ?> · Opened <?= format_date($ticket['created_at'], true) ?></p></div><span class="status-pill status-<?= e($ticket['status']) ?> large"><?= e(ucwords(str_replace('_',' ',$ticket['status']))) ?></span></div><div class="student-conversation-layout"><section class="card conversation"><?php foreach($messages as $message):?><article class="<?= $message['is_staff_reply']?'staff':'' ?>"><span class="initial-avatar"><?= e(strtoupper(substr($message['sender_name'],0,1))) ?></span><div><header><b><?= e($message['sender_name']) ?></b><small><?= $message['is_staff_reply']?'Admissions team':'You' ?> · <?= format_date($message['created_at'],true) ?></small></header><p><?= nl2br(e($message['message'])) ?></p></div></article><?php endforeach?></section><aside class="card ticket-reply"><span class="eyebrow">Continue conversation</span><h2>Add a reply</h2><?php if($ticket['status']==='closed'):?><div class="alert alert-warning">This ticket is closed. Create a new ticket if you still need help.</div><?php else:?><form method="post" action="<?= url('student/support/'.$ticket['id']) ?>"><?= csrf_field() ?><label><span>Message</span><textarea name="message" rows="8" maxlength="3000" required placeholder="Add any details that will help the admissions team…"></textarea></label><button class="button button-primary button-block">Send reply →</button></form><?php endif?><p>Replies remain linked to your applicant account and are visible only to you and authorised staff.</p></aside></div>
